   struct brcmf_scan_params_v2_le params_v2_le;
   struct cfg80211_scan_request *scan_request;
   u64 reqid;
   u32 bucket;
   s32 err = 0;
   brcmf_dbg(SCAN, "Enter\n");
   scan_request = cfg->scan_request;
   cfg->scan_request = NULL;
   timer_delete_sync(&cfg->escan_timeout);
    if (fw_abort) {
        brcmf_dbg(SCAN, "ABORT scan in firmware\n");
        brcmf_escan_prep(cfg, &params_v2_le, NULL);
        if (brcmf_feat_is_enabled(ifp, BRCMF_FEAT_SCAN_V2)) {
            err = brcmf_fil_cmd_data_set(ifp, BRCMF_C_SCAN, &params_v2_le, sizeof(params_v2_le));
        } else {
            struct brcmf_scan_params_le params_le;
            brcmf_scan_params_v2_to_v1(&params_v2_le, &params_le);
            err = brcmf_fil_cmd_data_set(ifp, BRCMF_C_SCAN, &params_le, sizeof(params_le));
        }
        if (err) {
            bphy_err(drvr, "Scan abort failed\n");
        }
    }

   brcmf_scan_config_mpc(ifp, 1);
    if (cfg->int_escan_map) {
        brcmf_dbg(SCAN, "scheduled scan completed (%x)\n", cfg->int_escan_map);
        while (cfg->int_escan_map) {
            bucket = __ffs(cfg->int_escan_map);
            cfg->int_escan_map &= ~BIT(bucket);
            reqid = brcmf_pno_find_reqid_by_bucket(cfg->pno, bucket);
            if (!aborted) {
                brcmf_dbg(SCAN, "report results: reqid=%llu\n", reqid);
                cfg80211_sched_scan_results(cfg_to_wiphy(cfg), reqid);
            }
        }
    } else if (scan_request) {
        struct cfg80211_scan_info info = {
            .aborted = aborted,
        };
        brcmf_dbg(SCAN, "ESCAN Completed scan: %s\n", aborted ? "Aborted" : "Done");
        cfg80211_scan_done(scan_request, &info);
    }
    if (!test_and_clear_bit(BRCMF_SCAN_STATUS_BUSY, &cfg->scan_status)) {
        brcmf_dbg(SCAN, "Scan complete, probably P2P scan\n");
    }

   return err;
}

