        return false;
    }

   if (ksmbd_conn_exiting(conn)) {
       return false;
   }
    if (kthread_should_stop()) {
        return false;
    }
    if (atomic_read(&conn->stats.open_files_count) > 0) {
        return true;
    }
    if (server_conf.deadtime > 0 && time_after(jiffies, conn->last_active + server_conf.deadtime)) {
        ksmbd_debug(CONN, "No response from client in %lu minutes\n", server_conf.deadtime / SMB_ECHO_TERVAL);
        return false;
    }

   return true;
}

