    } else {
        delay = 0;
    }

   current_hweight(iocg, &hwa, NULL);
   vover = atomic64_read(&iocg->vtime) + abs_cost_to_cost(iocg->abs_vdebt, hwa) - now->vnow;
   vover_pct = div64_s64(100 * vover, ioc->period_us * ioc->vtime_base_rate);
    if (vover_pct <= M_DELAY_THR_PCT) {
        new_delay = 0;
    } else if (vover_pct >= MAX_DELAY_THR_PCT) {
        new_delay = MAX_DELAY;
    } else {
