   phb->bus = NULL;
   pci_remove_bus(b);
   host_bridge->bus = NULL;
   device_unregister(&host_bridge->dev);
    if (res->flags & IORESOURCE_IO) {
        release_resource(res);
    }
    for (i = 0; i < 3; ++i) {
        res = &phb->mem_resources[i];
        if (!(res->flags & IORESOURCE_MEM)) {
            continue;
        }
        release_resource(res);
    }

   put_device(&host_bridge->dev);
   return 0;
}

