   struct ksmbd_transport *t = conn->transport;
   unsigned int pdu_size, max_allowed_pdu_size;
   char hdr_buf[4] = {0,};
   int size;
   mutex_init(&conn->srv_mutex);
   __module_get(THIS_MODULE);
    if (t->ops->prepare && t->ops->prepare(t)) {
        goto out;
    }

   conn->last_active = jiffies;
    while (ksmbd_conn_alive(conn)) {
        if (try_to_freeze()) {
            continue;
        }
        kvfree(conn->request_buf);
        conn->request_buf = NULL;
        size = t->ops->read(t, hdr_buf, sizeof(hdr_buf), -1);
        if (size != sizeof(hdr_buf)) {
            break;
        }
        pdu_size = get_rfc1002_len(hdr_buf);
        ksmbd_debug(CONN, "RFC1002 header %u bytes\n", pdu_size);
        if (ksmbd_conn_good(conn)) {
            max_allowed_pdu_size = SMB3_MAX_MSGSIZE + conn->vals->max_write_size;
        } else {
            max_allowed_pdu_size = SMB3_MAX_MSGSIZE;
        }
        if (pdu_size > max_allowed_pdu_size) {
            pr_err_ratelimited("PDU length(%u) exceeded maximum allowed pdu size(%u) on connection(%d)\n", pdu_size, max_allowed_pdu_size, READ_ONCE(conn->status));
            break;
        }
        if (pdu_size > MAX_STREAM_PROT_LEN) {
            break;
        }
        size = pdu_size + 4 + 1;
        conn->request_buf = kvmalloc(size, GFP_KERNEL);
        if (!conn->request_buf) {
            break;
        }
        memcpy(conn->request_buf, hdr_buf, sizeof(hdr_buf));
        if (!ksmbd_smb_request(conn)) {
            break;
        }
        size = t->ops->read(t, conn->request_buf + 4, pdu_size, 2);
        if (size < 0) {
            pr_err("sock_read failed: %d\n", size);
            break;
        }
        if (size != pdu_size) {
            pr_err("PDU error. Read: %d, Expected: %d\n", size, pdu_size);
            continue;
        }
        if (!default_conn_ops.process_fn) {
            pr_err("No connection request callback\n");
            break;
        }
        if (default_conn_ops.process_fn(conn)) {
            pr_err("Cannot handle request\n");
            break;
        }
    }

out:
   ksmbd_conn_set_releasing(conn);
   wait_event(conn->r_count_q, atomic_read(&conn->r_count) == 0);
    if (IS_ENABLED(CONFIG_UNICODE)) {
        utf8_unload(conn->um);
    }

   unload_nls(conn->local_nls);
    if (default_conn_ops.terminate_fn) {
        default_conn_ops.terminate_fn(conn);
    }

   t->ops->disconnect(t);
   module_put(THIS_MODULE);
   return 0;
}

